def add_spaces_to_text(input_text):
    output_text = ""
    i = 0
    while i < len(input_text):
        if input_text[i].isalpha():
            start = i
            while i < len(input_text) and input_text[i].isalpha():
                i += 1
            output_text += input_text[start:i] + " "
        else:
            output_text += input_text[i]
            if input_text[i] in '.,!?' and i + 1 < len(input_text) and input_text[i + 1] != ' ':
                output_text += " "
            i += 1
    return output_text.strip()

